/**
 * Domain types re-exported from the generated OpenAPI schema.
 *
 * `schema.d.ts` is generated by `npm run api:types` from `docs/api/openapi.yaml`.
 * Never restate an API shape by hand (frontend.md §1) — add an alias here instead.
 */
import type { components, paths } from './schema'

type Schemas = components['schemas']

export type Level = Schemas['Level']
export type LockState = Schemas['LockState']
export type LessonStatus = Schemas['LessonStatus']
export type ResourceKind = Schemas['ResourceKind']
export type ActivityKind = Schemas['ActivityKind']
export type Role = Schemas['Role']

export type Problem = Schemas['Problem']
export type CourseSummary = Schemas['CourseSummary']
export type Course = Schemas['Course']
export type ModuleSummary = Schemas['ModuleSummary']
export type Module = Schemas['Module']
export type LessonSummary = Schemas['LessonSummary']
export type Lesson = Schemas['Lesson']
export type Activity = Schemas['Activity']
export type ResourceRef = Schemas['ResourceRef']
export type Roadmap = Schemas['Roadmap']
export type Status = Schemas['Status']
export type LessonState = Schemas['LessonState']
export type LessonProgress = Schemas['LessonProgress']
export type NextLesson = Schemas['NextLesson']
export type DoneResult = Schemas['DoneResult']
export type StudySession = Schemas['StudySession']
export type SearchHit = Schemas['SearchHit']
export type Report = Schemas['Report']

/** A stage of the roadmap: one level with its modules. */
export type RoadmapStage = NonNullable<Roadmap['stages']>[number]
/** A module inside a roadmap stage (id, title, progress, lock state, lessons). */
export type RoadmapModule = NonNullable<RoadmapStage['modules']>[number]
/** A lesson inside a roadmap module. */
export type RoadmapLesson = NonNullable<RoadmapModule['lessons']>[number]
/** A stage of the dashboard status payload (no lesson list). */
export type StatusStage = NonNullable<Status['stages']>[number]
/** `Status.current` — the learner's current module and next lesson. */
export type StatusCurrent = NonNullable<Status['current']>
/** One entry of `Status.recent`. */
export type RecentActivity = NonNullable<Status['recent']>[number]

/** Paths that expose a GET operation. */
export type GetPath = {
  [K in keyof paths]: paths[K] extends { get: Record<string, unknown> } ? K : never
}[keyof paths]

/** The 200 `application/json` body of a GET operation. */
export type GetResponse<P extends GetPath> = paths[P] extends {
  get: { responses: { 200: { content: { 'application/json': infer T } } } }
}
  ? T
  : never

/** Paths that expose a POST operation. */
export type PostPath = {
  [K in keyof paths]: paths[K] extends { post: Record<string, unknown> } ? K : never
}[keyof paths]
